package com.codeguardian.service.tools; import com.codeguardian.entity.Finding; import com.github.javaparser.StaticJavaParser; import org.springframework.stereotype.Component; import java.util.*; @Component public class JavaParserAnalysisTool{public List<Finding> analyze(String code){try{StaticJavaParser.parse(code);return List.of();}catch(Exception e){return List.of(Finding.builder().severity("HIGH").title("Java syntax error").location("Source").description(e.getMessage()).suggestion("Fix the Java syntax before review.").category("BUG").build());}}}
